import{_ as t,o as e,c as s,a4 as n}from"./chunks/framework.BUqnS5H7.js";const o=JSON.parse('{"title":"数据页与存储结构","description":"","frontmatter":{"doc_id":"pg-data-page","title":"数据页与存储结构"},"headers":[],"relativePath":"postgresql/02-architecture/chapter-03-data-page.md","filePath":"postgresql/02-architecture/chapter-03-data-page.md"}'),l={name:"postgresql/02-architecture/chapter-03-data-page.md"};function p(r,a,d,i,c,g){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="数据页与存储结构" tabindex="-1" data-src-line="2" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">数据页与存储结构 <a class="header-anchor" href="#数据页与存储结构" aria-label="Permalink to &quot;数据页与存储结构&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><p data-src-line="4" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>核心问题：</strong> PostgreSQL 中一张表的数据在磁盘上是如何组织的？8KB 的数据页内部是什么结构？大字段（如 JSONB、大文本）是怎么存的？理解存储结构，是理解 VACUUM、索引扫描和 IO 性能的前提。</p></blockquote><h2 id="_1-逻辑结构层次" tabindex="-1" data-src-line="6" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">1. 逻辑结构层次 <a class="header-anchor" href="#_1-逻辑结构层次" aria-label="Permalink to &quot;1. 逻辑结构层次&quot;">​</a></h2><p data-src-line="8" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">PostgreSQL 的逻辑结构从大到小依次为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Database Cluster (集群)</span></span>
<span class="line"><span>  └── Database (数据库)</span></span>
<span class="line"><span>        └── Schema (模式)</span></span>
<span class="line"><span>              └── Table (表)</span></span>
<span class="line"><span>                    └── Page (数据页, 8KB)</span></span>
<span class="line"><span>                          └── Tuple (元组/行)</span></span></code></pre></div><table tabindex="0"><thead data-src-line="19" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="19" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">层次</th><th style="text-align:left;">说明</th><th style="text-align:left;">对应 Java 类比</th></tr></thead><tbody data-src-line="21" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="21" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>Database Cluster</strong></td><td style="text-align:left;">一个 PG 实例管理的所有数据库</td><td style="text-align:left;">一个 MySQL Instance</td></tr><tr data-src-line="22" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>Database</strong></td><td style="text-align:left;">独立的数据库，不同 DB 之间默认隔离</td><td style="text-align:left;">MySQL 的 Database</td></tr><tr data-src-line="23" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>Schema</strong></td><td style="text-align:left;">数据库内的命名空间，隔离表/视图等对象</td><td style="text-align:left;">无直接对应（MySQL schema ≈ database）</td></tr><tr data-src-line="24" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>Table</strong></td><td style="text-align:left;">存储数据的表</td><td style="text-align:left;">同 MySQL</td></tr><tr data-src-line="25" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>Page</strong></td><td style="text-align:left;">磁盘 I/O 的最小单位，固定 8KB</td><td style="text-align:left;">类似 InnoDB 的 Page（16KB）</td></tr><tr data-src-line="26" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>Tuple</strong></td><td style="text-align:left;">表中的一行记录</td><td style="text-align:left;">Row / Record</td></tr></tbody></table><blockquote data-src-line="28" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><p data-src-line="28" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>Java 开发者注意：</strong> PG 的 Schema 是 Database 下级的概念，与 MySQL 不同。MySQL 中 <code>CREATE DATABASE</code> 和 <code>CREATE SCHEMA</code> 几乎等价，但 PG 中两者是不同的层级。</p></blockquote><h2 id="_2-数据页结构-8kb" tabindex="-1" data-src-line="30" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">2. 数据页结构（8KB） <a class="header-anchor" href="#_2-数据页结构-8kb" aria-label="Permalink to &quot;2. 数据页结构（8KB）&quot;">​</a></h2><p data-src-line="32" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">每个数据页固定为 <strong>8192 字节（8KB）</strong>，内部结构如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────┐  偏移 0</span></span>
<span class="line"><span>│           PageHeaderData (24 字节)        │</span></span>
<span class="line"><span>│  - pd_lsn: 最后修改该页的 WAL LSN          │</span></span>
<span class="line"><span>│  - pd_checksum: 页校验和(PG 12+)          │</span></span>
<span class="line"><span>│  - pd_lower: ItemId 数组末尾指针           │</span></span>
<span class="line"><span>│  - pd_upper: Tuple 数据起始指针            │</span></span>
<span class="line"><span>│  - pd_special: 特殊空间起始指针             │</span></span>
<span class="line"><span>│  - pd_pagesize_version: 页大小+版本        │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤  偏移 24</span></span>
<span class="line"><span>│           ItemId 数组 (行指针)             │</span></span>
<span class="line"><span>│  [ItemId 1][ItemId 2][ItemId 3]...       │</span></span>
<span class="line"><span>│  每个 ItemId 4 字节: (offset, length,     │</span></span>
<span class="line"><span>│                       flag)              │</span></span>
<span class="line"><span>│  从前往后增长 ←──── pd_lower               │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│              Free Space                  │</span></span>
<span class="line"><span>│          (未使用的中间空间)                 │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│           Tuple 数据区                    │</span></span>
<span class="line"><span>│  ...[Tuple 3][Tuple 2][Tuple 1]          │</span></span>
<span class="line"><span>│  从后往前增长 ────→ pd_upper               │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤  偏移 Special</span></span>
<span class="line"><span>│         Special Space (索引页专用)         │</span></span>
<span class="line"><span>│   堆表页中为空，索引页存储索引特定数据         │</span></span>
<span class="line"><span>└──────────────────────────────────────────┘  偏移 8192</span></span></code></pre></div><h3 id="pageheader-字段详解" tabindex="-1" data-src-line="62" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">PageHeader 字段详解 <a class="header-anchor" href="#pageheader-字段详解" aria-label="Permalink to &quot;PageHeader 字段详解&quot;">​</a></h3><table tabindex="0"><thead data-src-line="64" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="64" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">字段</th><th style="text-align:left;">大小</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="66" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="66" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>pd_lsn</code></td><td style="text-align:left;">8 字节</td><td style="text-align:left;">最后修改该页的 WAL 记录的 LSN，用于恢复判断</td></tr><tr data-src-line="67" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>pd_checksum</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">页校验和（PG 12+，需 initdb 时开启 <code>--data-checksums</code>）</td></tr><tr data-src-line="68" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>pd_lower</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">ItemId 数组的结束位置（空闲空间起点）</td></tr><tr data-src-line="69" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>pd_upper</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">Tuple 数据的起始位置（空闲空间终点）</td></tr><tr data-src-line="70" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>pd_special</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">特殊空间的起始偏移</td></tr><tr data-src-line="71" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>pd_pagesize_version</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">页大小和布局版本号</td></tr></tbody></table><h3 id="itemid-行指针" tabindex="-1" data-src-line="73" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">ItemId（行指针） <a class="header-anchor" href="#itemid-行指针" aria-label="Permalink to &quot;ItemId（行指针）&quot;">​</a></h3><p data-src-line="75" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">每个 ItemId 占 <strong>4 字节</strong>，记录对应 Tuple 在页内的偏移和长度。ItemId 数组从页头开始向后增长，Tuple 数据从页尾开始向前增长，中间是 Free Space。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ItemId 结构 (4 bytes):</span></span>
<span class="line"><span>┌──────────────────────────────────┐</span></span>
<span class="line"><span>│  offset (15 bits) | flags (2 bits) | length (15 bits) │</span></span>
<span class="line"><span>└──────────────────────────────────┘</span></span></code></pre></div><h2 id="_3-堆表-heap-table-存储方式" tabindex="-1" data-src-line="84" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">3. 堆表（Heap Table）存储方式 <a class="header-anchor" href="#_3-堆表-heap-table-存储方式" aria-label="Permalink to &quot;3. 堆表（Heap Table）存储方式&quot;">​</a></h2><p data-src-line="86" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">PostgreSQL 默认使用 <strong>堆表（Heap Table）</strong> 存储数据，即行记录无序地存放在数据页中。</p><h3 id="_3-1-tuple-元组-结构" tabindex="-1" data-src-line="88" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">3.1 Tuple（元组）结构 <a class="header-anchor" href="#_3-1-tuple-元组-结构" aria-label="Permalink to &quot;3.1 Tuple（元组）结构&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────┐</span></span>
<span class="line"><span>│        HeapTupleHeaderData         │</span></span>
<span class="line"><span>│  (23~27 字节，含对齐)                │</span></span>
<span class="line"><span>│                                    │</span></span>
<span class="line"><span>│  t_xmin:   插入该元组的事务 ID        │</span></span>
<span class="line"><span>│  t_xmax:   删除/锁定该元组的事务ID    │</span></span>
<span class="line"><span>│  t_cid:    命令 ID (同一事务内序号)   │</span></span>
<span class="line"><span>│  t_ctid:   当前元组的物理位置         │</span></span>
<span class="line"><span>│            (page_number, offset)   │</span></span>
<span class="line"><span>│  t_infomask: 元组状态标志位          │</span></span>
<span class="line"><span>│  t_hoff:   用户数据起始偏移           │</span></span>
<span class="line"><span>├────────────────────────────────────┤</span></span>
<span class="line"><span>│         Null Bitmap (可选)          │</span></span>
<span class="line"><span>│   标记哪些列为 NULL                  │</span></span>
<span class="line"><span>├────────────────────────────────────┤</span></span>
<span class="line"><span>│         用户数据 (列值)              │</span></span>
<span class="line"><span>│   按列定义顺序存储                    │</span></span>
<span class="line"><span>│   变长列: 1~4 字节长度前缀 + 数据      │</span></span>
<span class="line"><span>└────────────────────────────────────┘</span></span></code></pre></div><h3 id="_3-2-多版本并发控制-mvcc" tabindex="-1" data-src-line="112" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">3.2 多版本并发控制（MVCC） <a class="header-anchor" href="#_3-2-多版本并发控制-mvcc" aria-label="Permalink to &quot;3.2 多版本并发控制（MVCC）&quot;">​</a></h3><p data-src-line="114" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">PG 的 MVCC 直接体现在 Tuple 头部：</p><table tabindex="0"><thead data-src-line="116" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="116" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">操作</th><th style="text-align:left;">行为</th></tr></thead><tbody data-src-line="118" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="118" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>INSERT</strong></td><td style="text-align:left;">写入新 Tuple，<code>t_xmin</code> = 当前事务 ID</td></tr><tr data-src-line="119" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>UPDATE</strong></td><td style="text-align:left;">旧行标记删除（<code>t_xmax</code> = 当前事务 ID），新行作为新 Tuple 插入</td></tr><tr data-src-line="120" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>DELETE</strong></td><td style="text-align:left;">不物理删除，仅设置 <code>t_xmax</code> = 当前事务 ID</td></tr><tr data-src-line="121" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>SELECT</strong></td><td style="text-align:left;">根据 <code>t_xmin</code>、<code>t_xmax</code> 和事务快照判断可见性</td></tr></tbody></table><blockquote data-src-line="123" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><p data-src-line="123" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>与 MySQL 的关键区别：</strong> InnoDB 将旧版本存放在 Undo Log 中，表中只保留最新版本；PG 直接在表中保留多个版本。这意味着 PG 的 UPDATE 实际上是 DELETE + INSERT，会产生更多死元组（dead tuples），需要 VACUUM 清理。</p></blockquote><h2 id="_4-toast-机制-大字段存储" tabindex="-1" data-src-line="125" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">4. TOAST 机制（大字段存储） <a class="header-anchor" href="#_4-toast-机制-大字段存储" aria-label="Permalink to &quot;4. TOAST 机制（大字段存储）&quot;">​</a></h2><p data-src-line="127" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>TOAST（The Oversized-Attribute Storage Technique）</strong> 是 PG 处理大字段的机制。当一行数据超过单页容量时，大字段值会被&quot;弹出&quot;到独立的 TOAST 表中。</p><h3 id="toast-触发条件" tabindex="-1" data-src-line="129" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">TOAST 触发条件 <a class="header-anchor" href="#toast-触发条件" aria-label="Permalink to &quot;TOAST 触发条件&quot;">​</a></h3><ul data-src-line="131" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><li data-src-line="131" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">单个 Tuple 超过约 <strong>2KB</strong>（约 1/4 页）时，PG 会尝试 TOAST</li><li data-src-line="132" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">TOAST 表的命名格式：<code>pg_toast.pg_toast_&lt;oid&gt;</code></li></ul><blockquote data-src-line="134" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><p data-src-line="134" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>OID（对象标识符）</strong>：PG 给每个数据库对象（表、索引、序列等）分配的唯一整数编号。<code>pg_toast_&lt;oid&gt;</code> 里的 <code>&lt;oid&gt;</code> 是原表的 OID，据此把 TOAST 表关联回原表。§6 里 <code>base/&lt;oid&gt;</code> 目录名同理，是数据库的 OID。</p></blockquote><h3 id="toast-存储策略" tabindex="-1" data-src-line="136" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">TOAST 存储策略 <a class="header-anchor" href="#toast-存储策略" aria-label="Permalink to &quot;TOAST 存储策略&quot;">​</a></h3><table tabindex="0"><thead data-src-line="138" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="138" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">策略</th><th style="text-align:left;">说明</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="140" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="140" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>PLAIN</strong></td><td style="text-align:left;">不压缩，不外部存储</td><td style="text-align:left;">小字段（默认值）</td></tr><tr data-src-line="141" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>EXTENDED</strong></td><td style="text-align:left;">先压缩，压缩后仍太大则外部存储</td><td style="text-align:left;">TEXT、BYTEA（默认策略）</td></tr><tr data-src-line="142" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>EXTERNAL</strong></td><td style="text-align:left;">不压缩，直接外部存储</td><td style="text-align:left;">不需要压缩的大字段</td></tr><tr data-src-line="143" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>MAIN</strong></td><td style="text-align:left;">压缩，尽量不外部存储</td><td style="text-align:left;">需要尽量保留在行内的字段</td></tr></tbody></table><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  主表 (Heap Table)                │</span></span>
<span class="line"><span>│                                                  │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────────┐    │</span></span>
<span class="line"><span>│  │ Tuple: [col1] [col2] [col3→TOAST Pointer]│    │</span></span>
<span class="line"><span>│  └──────────────┬───────────────────────────┘    │</span></span>
<span class="line"><span>│                 │                                │</span></span>
<span class="line"><span>│                 ▼ TOAST Pointer                  │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────────┐    │</span></span>
<span class="line"><span>│  │ TOAST 表 (pg_toast.pg_toast_xxxxx)       │    │</span></span>
<span class="line"><span>│  │                                          │    │</span></span>
<span class="line"><span>│  │  Chunk 1: [chunk_id, seq, data...]       │    │</span></span>
<span class="line"><span>│  │  Chunk 2: [chunk_id, seq, data...]       │    │</span></span>
<span class="line"><span>│  │  Chunk 3: [chunk_id, seq, data...]       │    │</span></span>
<span class="line"><span>│  │  ...                                     │    │</span></span>
<span class="line"><span>│  │  (每个 chunk 默认 2KB)                    │    │</span></span>
<span class="line"><span>│  └──────────────────────────────────────────┘    │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><blockquote data-src-line="166" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><p data-src-line="166" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>实践建议：</strong> 对于 JSONB 列中可能存储大 JSON 文档的场景，注意 TOAST 的存在。频繁访问 TOAST 存储的列会产生额外的 I/O。如果大部分查询不需要该大字段，可以考虑拆表或使用延迟加载。</p></blockquote><h2 id="_5-表空间-tablespace" tabindex="-1" data-src-line="168" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">5. 表空间（Tablespace） <a class="header-anchor" href="#_5-表空间-tablespace" aria-label="Permalink to &quot;5. 表空间（Tablespace）&quot;">​</a></h2><p data-src-line="170" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">表空间定义了数据库对象在文件系统中的存储位置。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              表空间 (Tablespace)              │</span></span>
<span class="line"><span>│                                              │</span></span>
<span class="line"><span>│  pg_default (默认表空间)                      │</span></span>
<span class="line"><span>│  → $PGDATA/base/                             │</span></span>
<span class="line"><span>│                                              │</span></span>
<span class="line"><span>│  pg_global (全局共享表空间)                    │</span></span>
<span class="line"><span>│  → $PGDATA/global/                           │</span></span>
<span class="line"><span>│                                              │</span></span>
<span class="line"><span>│  自定义表空间:                                │</span></span>
<span class="line"><span>│  → 指定目录下的 PG_VERSION 文件               │</span></span>
<span class="line"><span>│  → 可指向不同磁盘/SSD                        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead data-src-line="188" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="188" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">用途</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="190" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="190" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>磁盘空间管理</strong></td><td style="text-align:left;">将大表放在高速 SSD，小表放在 HDD</td></tr><tr data-src-line="191" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>I/O 隔离</strong></td><td style="text-align:left;">将热点表和冷数据表分离到不同磁盘</td></tr><tr data-src-line="192" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><strong>备份策略</strong></td><td style="text-align:left;">不同表空间可以使用不同的备份策略</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 创建表空间</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLESPACE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fast_ssd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LOCATION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/mnt/ssd/pg_data&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 在指定表空间创建表</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> orders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BIGSERIAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> JSONB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) TABLESPACE fast_ssd;</span></span></code></pre></div><h2 id="_6-数据目录结构" tabindex="-1" data-src-line="205" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">6. 数据目录结构 <a class="header-anchor" href="#_6-数据目录结构" aria-label="Permalink to &quot;6. 数据目录结构&quot;">​</a></h2><p data-src-line="207" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><code>$PGDATA</code> 目录是 PG 集群的根目录，主要结构如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$PGDATA/</span></span>
<span class="line"><span>├── base/                  # 各数据库的数据文件</span></span>
<span class="line"><span>│   ├── 1/                 # template1 的数据</span></span>
<span class="line"><span>│   ├── 13587/             # 用户数据库的数据（OID 为键）</span></span>
<span class="line"><span>│   │   ├── 16384          # 表的数据文件（relfilenode）</span></span>
<span class="line"><span>│   │   ├── 16384.1        # 表的 FSM（Free Space Map）</span></span>
<span class="line"><span>│   │   ├── 16384.2        # 表的 VM（Visibility Map）</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── global/                # 集群共享数据（pg_database, pg_authid 等）</span></span>
<span class="line"><span>├── pg_wal/                # WAL 日志文件</span></span>
<span class="line"><span>│   ├── 000000010000000000000001  # WAL 段文件 (16MB)</span></span>
<span class="line"><span>│   ├── 000000010000000000000002</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>├── pg_xact/               # 事务提交状态（CLOG）</span></span>
<span class="line"><span>├── pg_tblspc/             # 表空间符号链接</span></span>
<span class="line"><span>├── pg_stat_tmp/           # 统计信息临时文件</span></span>
<span class="line"><span>├── pg_logical/            # 逻辑复制相关数据</span></span>
<span class="line"><span>├── pg_commit_ts/          # 事务提交时间戳</span></span>
<span class="line"><span>├── postgresql.conf        # 主配置文件</span></span>
<span class="line"><span>├── pg_hba.conf            # 客户端认证配置</span></span>
<span class="line"><span>├── pg_ident.conf          # 用户名映射</span></span>
<span class="line"><span>├── postmaster.pid         # Postmaster PID 文件</span></span>
<span class="line"><span>├── postmaster.opts        # 启动参数记录</span></span>
<span class="line"><span>└── PG_VERSION             # PG 主版本号</span></span></code></pre></div><h3 id="数据文件命名规则" tabindex="-1" data-src-line="237" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">数据文件命名规则 <a class="header-anchor" href="#数据文件命名规则" aria-label="Permalink to &quot;数据文件命名规则&quot;">​</a></h3><table tabindex="0"><thead data-src-line="239" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="239" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">文件后缀</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="241" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="241" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">无后缀</td><td style="text-align:left;">表/索引的主数据文件（大小 = N × 8KB）</td></tr><tr data-src-line="242" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>.1</code>, <code>.2</code>, ...</td><td style="text-align:left;">超过 1GB 的表自动分段（段文件）</td></tr><tr data-src-line="243" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>_fsm</code></td><td style="text-align:left;">Free Space Map — 记录每个数据页的空闲空间</td></tr><tr data-src-line="244" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;"><code>_vm</code></td><td style="text-align:left;">Visibility Map — 记录哪些页的所有元组都可见（用于 Index-Only Scan 和 VACUUM 跳过）</td></tr></tbody></table><h3 id="fsm-和-vm-的作用" tabindex="-1" data-src-line="246" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">FSM 和 VM 的作用 <a class="header-anchor" href="#fsm-和-vm-的作用" aria-label="Permalink to &quot;FSM 和 VM 的作用&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表数据文件: 16384</span></span>
<span class="line"><span>  ├── 16384        (主数据文件，存储实际 Tuple)</span></span>
<span class="line"><span>  ├── 16384_fsm    (Free Space Map: 记录每页空闲空间大小)</span></span>
<span class="line"><span>  │   → INSERT 时快速找到有足够空间的页，避免全表扫描</span></span>
<span class="line"><span>  └── 16384_vm     (Visibility Map: 标记全可见页)</span></span>
<span class="line"><span>      → Index-Only Scan: 只需检查 VM 而非回表</span></span>
<span class="line"><span>      → VACUUM: 跳过全可见页，减少扫描量</span></span></code></pre></div><blockquote data-src-line="258" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><p data-src-line="258" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><strong>性能关联：</strong> 当表膨胀严重时，FSM 无法有效指导空间分配，导致 INSERT 变慢。此时需要 <code>VACUUM FULL</code> 或 <code>pg_repack</code> 来回收空间。VM 对 Index-Only Scan 至关重要 — 如果 VM 标记不准确，优化器会选择普通 Index Scan 而非 Index-Only Scan。</p></blockquote><h2 id="本章小结" tabindex="-1" data-src-line="260" data-src-file="postgresql/02-architecture/chapter-03-data-page.md">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><table tabindex="0"><thead data-src-line="262" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="262" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><th style="text-align:left;">要点</th><th style="text-align:left;">记忆关键词</th></tr></thead><tbody data-src-line="264" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><tr data-src-line="264" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">PG 数据页固定 8KB</td><td style="text-align:left;">比 InnoDB 的 16KB 小一半</td></tr><tr data-src-line="265" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">PageHeader + ItemId + Tuple + Free Space</td><td style="text-align:left;">ItemId 从前往后，Tuple 从后往前</td></tr><tr data-src-line="266" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">堆表存储，MVCC 在 Tuple 头部</td><td style="text-align:left;">UPDATE = DELETE + INSERT，产生死元组</td></tr><tr data-src-line="267" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">TOAST 处理大字段</td><td style="text-align:left;">超 2KB 触发，chunk 分片存储</td></tr><tr data-src-line="268" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">FSM 加速插入，VM 加速 Index-Only Scan</td><td style="text-align:left;">膨胀问题的诊断切入点</td></tr><tr data-src-line="269" data-src-file="postgresql/02-architecture/chapter-03-data-page.md"><td style="text-align:left;">base/ 存数据，pg_wal/ 存 WAL</td><td style="text-align:left;">按 OID 和 relfilenode 组织</td></tr></tbody></table>`,47)])])}const u=t(l,[["render",p]]);export{o as __pageData,u as default};
